import sys

def count_primes(n: int) -> int:
    if n <= 2:
        return 0
    if n == 3:
        return 1
    # Sieve of Eratosthenes for odd numbers only
    size = n // 2
    sieve = bytearray([1]) * size
    sieve[0] = 0
    limit = int(n ** 0.5)
    for i in range(1, limit // 2 + 1):
        if sieve[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            sieve[start::p] = bytearray((size - start - 1) // p + 1)
    # Count 2 (if n > 2) plus odd primes < n
    if n % 2 == 0:
        return sum(sieve) + 1
    else:
        return sum(sieve) + 1

if __name__ == "__main__":
